import{_ as t,C as r,o as s,c as a,E as n,a2 as i}from"./chunks/framework.DUPQTP2q.js";const f=JSON.parse('{"title":"Free App Store and Google Play Screenshot Creator","description":"Create app store screenshots with descriptions, solid backgrounds, and continuous gradients. Export iPhone, iPad, and Android screenshots privately in your browser.","frontmatter":{"title":"Free App Store and Google Play Screenshot Creator","description":"Create app store screenshots with descriptions, solid backgrounds, and continuous gradients. Export iPhone, iPad, and Android screenshots privately in your browser.","pageClass":"crop-tool-layout","permalink":"/appscreenshots/","canonicalUrl":"https://curvednebula.com/appscreenshots/","meta":[{"name":"keywords","content":"app screenshot creator, app store screenshot maker, Google Play screenshots, iPhone screenshots, iPad screenshots, Android screenshot creator, panoramic screenshot background"},{"property":"og:title","content":"Free App Store and Google Play Screenshot Creator"},{"property":"og:description","content":"Turn app screenshots into a connected set with descriptions, solid colors, and continuous gradients. Everything stays on your device."},{"property":"og:type","content":"website"},{"property":"og:url","content":"https://curvednebula.com/appscreenshots/"},{"name":"twitter:card","content":"summary"},{"name":"twitter:title","content":"Free App Store and Google Play Screenshot Creator"},{"name":"twitter:description","content":"Create and download app store screenshots with descriptions and connected backgrounds, privately in your browser."}],"aside":false},"headers":[],"relativePath":"appscreenshots/index.md","filePath":"appscreenshots/index.md"}'),c={name:"appscreenshots/index.md"};function d(h,e,p,l,u,g){const o=r("AppScreenshots");return s(),a("div",null,[n(o),e[0]||(e[0]=i('<h2 id="create-screenshots-for-your-app-s-store-listing" tabindex="-1">Create screenshots for your app’s store listing <a class="header-anchor" href="#create-screenshots-for-your-app-s-store-listing" aria-label="Permalink to &quot;Create screenshots for your app’s store listing&quot;">​</a></h2><p>Turn your app screenshots into a consistent set for the App Store or Google Play. Each image sits below a description, with space around it to show off your chosen background. Use a different solid color for each frame, or create a continuous gradient that flows across the entire sequence.</p><h3 id="how-to-use-the-screenshot-creator" tabindex="-1">How to use the screenshot creator <a class="header-anchor" href="#how-to-use-the-screenshot-creator" aria-label="Permalink to &quot;How to use the screenshot creator&quot;">​</a></h3><ol><li>Choose several PNG, JPEG, or WebP screenshots, or drag them into the editor.</li><li>Choose an Android phone, iPhone, or iPad output size. Swap width and height for landscape, or enter custom dimensions.</li><li>Select each frame and enter its description. Use the arrow buttons to change its position in the sequence.</li><li>Adjust screenshot size and the space reserved for text. Enable <strong>This frame only</strong> in the panel heading to customize the selected frame; leave it unchecked to edit the shared settings. Use the buttons above the selected frame to replace its image, reorder it, or remove it.</li><li>Set text size, font, weight, alignment, and color. Shorten overflowing descriptions or increase the text area before exporting.</li><li>In the <strong>Background</strong> panel, choose <strong>Solid color</strong> or <strong>Continuous gradient</strong>. <strong>This frame only</strong> gives the selected frame its own background type, color, and gradient settings. Leave it unchecked to edit the shared background.</li><li>Save the selected frame, or download all frames as numbered PNG or JPEG images in a ZIP.</li></ol><h3 id="how-does-the-continuous-gradient-work" tabindex="-1">How does the continuous gradient work? <a class="header-anchor" href="#how-does-the-continuous-gradient-work" aria-label="Permalink to &quot;How does the continuous gradient work?&quot;">​</a></h3><p>The gradient is drawn as if all frames were placed directly beside one another. Each exported image contains its own section, so adjacent edges match when the images are displayed in order. The preview adds a small gap between frames for selection; that gap is not part of the exported background. Reordering or adding frames redistributes the gradient across the new sequence. A solid-color frame still occupies its position in that sequence.</p><h3 id="which-output-sizes-are-available" tabindex="-1">Which output sizes are available? <a class="header-anchor" href="#which-output-sizes-are-available" aria-label="Permalink to &quot;Which output sizes are available?&quot;">​</a></h3><p>The presets include Android phone at 1080 × 1920, iPhone 6.9-inch at 1320 × 2868, and iPad 13-inch at 2064 × 2752 pixels, with landscape equivalents. Apple accepts specific sizes for each display category; Google Play also specifies image dimensions, aspect ratios, and screenshot counts. Check the <a href="https://developer.apple.com/help/app-store-connect/reference/app-information/screenshot-specifications/" target="_blank" rel="noreferrer">App Store screenshot specifications</a> and <a href="https://support.google.com/googleplay/android-developer/answer/9866151?hl=en" target="_blank" rel="noreferrer">Google Play preview asset requirements</a> for your app’s target devices. Custom dimensions are not automatically validated against store specifications.</p><h3 id="are-my-screenshots-uploaded" tabindex="-1">Are my screenshots uploaded? <a class="header-anchor" href="#are-my-screenshots-uploaded" aria-label="Permalink to &quot;Are my screenshots uploaded?&quot;">​</a></h3><p>No. Image editing and export happen locally in your browser. Images and descriptions are kept only in the current tab, so download your work before refreshing or leaving the page. PNG export produces RGB images without an alpha channel; JPEG exports also have opaque backgrounds. The tool creates image files for you to submit through your store account.</p>',10))])}const w=t(c,[["render",d]]);export{f as __pageData,w as default};
